		validator.validate( command );

            entity.setTelemetrySchemaId( command.getTelemetrySchemaId() );
            entity.setSchemaId( command.getSchemaId() );
            entity.setSchemaUri( command.getSchemaUri() );
            entity.setEncoding( command.getEncoding() );

		// ------------------------------------------
		// persist a new one
